// Guarded @json-render/core catalog, dynamic approval UI spec builder,
// and MCP Elicitation compiler for Loop Gateway.
//
// One validated json-render Spec ({ root, elements, state }) drives:
//   1. Terminal / IDE interactive option & field pickers (MCP elicitation/create)
//   2. Loop web dashboard focused approval dialogs (public/json-render-dom.js)
//   3. iMessage one-tap mobile pages (loop-text /text/approve/<token> & /form/<token>)
//
// Security invariant (OWASP ASI09): Approval UI specs are ALWAYS generated by the
// Loop Gateway from verified policy/tool records — never from LLM-authored text.

import {
  defineCatalog,
  defineSchema,
  evaluateVisibility,
  getByPath,
  resolveElementProps,
  validateSpec,
} from '@json-render/core';
import { z } from 'zod';
import { canAlwaysAllow } from './policies.mjs';

export const loopUiSchema = defineSchema((s) => ({
  spec: s.object({
    root: s.string(),
    elements: s.record(
      s.object({
        type: s.ref('catalog.components'),
        props: s.propsOf('catalog.components'),
        children: { ...s.array(s.string()), ...s.optional() },
        visible: { ...s.any(), ...s.optional() },
        on: { ...s.any(), ...s.optional() },
      }),
    ),
    state: { ...s.any(), ...s.optional() },
  }),
  catalog: s.object({
    components: s.map({
      props: s.zod(),
      slots: s.array(s.string()),
      description: s.string(),
    }),
    actions: s.map({
      params: s.zod(),
      description: s.string(),
    }),
  }),
}));

const OptionItemSchema = z.object({
  value: z.string().min(1).max(120),
  label: z.string().min(1).max(160),
  description: z.string().max(240).optional(),
});

const FactItemSchema = z.object({
  label: z.string().min(1).max(80),
  value: z.string().max(500),
  code: z.boolean().optional(),
});

export const loopUiCatalog = defineCatalog(loopUiSchema, {
  components: {
    Card: {
      props: z.object({
        kicker: z.string().max(120).optional(),
        title: z.string().max(240).optional(),
        subtitle: z.string().max(400).optional(),
        tone: z.enum(['default', 'warn', 'ok', 'danger']).optional(),
      }),
      slots: ['default'],
      description: 'Top-level card container for a focused prompt or approval.',
    },
    Stack: {
      props: z.object({
        direction: z.enum(['column', 'row']).optional(),
        gap: z.enum(['sm', 'md', 'lg']).optional(),
      }),
      slots: ['default'],
      description: 'Vertical or horizontal layout stack.',
    },
    Heading: {
      props: z.object({
        text: z.string().min(1).max(240),
        level: z.union([z.literal(1), z.literal(2), z.literal(3)]).optional(),
      }),
      slots: [],
      description: 'Section heading.',
    },
    Text: {
      props: z.object({
        text: z.string().max(1000),
        tone: z.enum(['default', 'muted', 'ok', 'warn', 'danger']).optional(),
        bold: z.boolean().optional(),
      }),
      slots: [],
      description: 'Plain text paragraph.',
    },
    Badge: {
      props: z.object({
        label: z.string().min(1).max(80),
        tone: z.enum(['default', 'ok', 'warn', 'danger']).optional(),
      }),
      slots: [],
      description: 'Compact status pill.',
    },
    Alert: {
      props: z.object({
        title: z.string().max(160).optional(),
        text: z.string().min(1).max(600),
        tone: z.enum(['info', 'warn', 'danger', 'ok']).optional(),
      }),
      slots: [],
      description: 'Highlighted notice or risk callout.',
    },
    FactList: {
      props: z.object({
        items: z.array(FactItemSchema).max(16),
      }),
      slots: [],
      description: 'List of verified key-value facts.',
    },
    CodeBlock: {
      props: z.object({
        label: z.string().max(120).optional(),
        code: z.string().max(4000),
        collapsible: z.boolean().optional(),
      }),
      slots: [],
      description: 'Monospace detail block (optionally collapsible).',
    },
    Divider: {
      props: z.object({}),
      slots: [],
      description: 'Subtle horizontal rule.',
    },
    Select: {
      props: z.object({
        name: z.string().min(1).max(60),
        label: z.string().min(1).max(120),
        hint: z.string().max(240).optional(),
        options: z.array(OptionItemSchema).min(1).max(32),
        defaultValue: z.string().max(120).optional(),
        optional: z.boolean().optional(),
      }),
      slots: [],
      description: 'Single-value dropdown selector.',
    },
    ChoiceGroup: {
      props: z.object({
        name: z.string().min(1).max(60),
        label: z.string().min(1).max(120),
        hint: z.string().max(240).optional(),
        options: z.array(OptionItemSchema).min(1).max(20),
        multiple: z.boolean().optional(),
        defaultValue: z.union([z.string().max(120), z.array(z.string().max(120))]).optional(),
        optional: z.boolean().optional(),
      }),
      slots: [],
      description: 'Single or multi-select option buttons.',
    },
    Toggle: {
      props: z.object({
        name: z.string().min(1).max(60),
        label: z.string().min(1).max(120),
        hint: z.string().max(240).optional(),
        defaultValue: z.boolean().optional(),
      }),
      slots: [],
      description: 'Boolean checkbox or switch.',
    },
    TextInput: {
      props: z.object({
        name: z.string().min(1).max(60),
        label: z.string().min(1).max(120),
        kind: z.enum(['text', 'email', 'password', 'code', 'number', 'long_text']).optional(),
        hint: z.string().max(240).optional(),
        placeholder: z.string().max(160).optional(),
        defaultValue: z.string().max(500).optional(),
        optional: z.boolean().optional(),
        secret: z.boolean().optional(),
      }),
      slots: [],
      description: 'Text, number, code, or password input.',
    },
    ActionGroup: {
      props: z.object({
        layout: z.enum(['stack', 'grid']).optional(),
      }),
      slots: ['default'],
      description: 'Container for primary and secondary decision buttons.',
    },
    Button: {
      props: z.object({
        label: z.string().min(1).max(120),
        tone: z.enum(['primary', 'secondary', 'danger']).optional(),
        action: z.enum(['decide', 'submit']).optional(),
        optionId: z.string().min(1).max(64).optional(),
        decision: z.enum(['approve', 'deny']).optional(),
        alwaysAllow: z.enum(['tool', 'connection']).optional(),
      }),
      slots: [],
      description: 'Interactive decision or submit button.',
    },
  },
  actions: {
    decide: {
      params: z.object({
        optionId: z.string().min(1).max(64),
        decision: z.enum(['approve', 'deny']),
        alwaysAllow: z.enum(['tool', 'connection']).optional(),
      }),
      description: 'Settle a Loop approval with an explicit gateway decision.',
    },
    submit: {
      params: z.object({}),
      description: 'Submit form answers back to the waiting agent.',
    },
  },
});

const MAX_SPEC_ELEMENTS = 64;

/** Strictly validates a json-render Spec structurally AND against loopUiCatalog. */
export function validateUiSpec(spec) {
  if (!spec || typeof spec !== 'object' || Array.isArray(spec)) {
    return { valid: false, errors: ['Spec must be a JSON object.'] };
  }
  const elements = spec.elements && typeof spec.elements === 'object' ? spec.elements : null;
  if (!elements || Object.keys(elements).length === 0 || Object.keys(elements).length > MAX_SPEC_ELEMENTS) {
    return { valid: false, errors: [`Spec must contain between 1 and ${MAX_SPEC_ELEMENTS} elements.`] };
  }
  const structural = validateSpec(spec);
  if (!structural.valid) {
    return {
      valid: false,
      errors: structural.issues.filter((i) => i.severity === 'error').map((i) => i.message),
    };
  }
  const catalogRes = loopUiCatalog.validate(spec);
  if (!catalogRes.success) {
    const issues = catalogRes.error?.issues?.map((i) => `${i.path.join('.') || 'spec'}: ${i.message}`) || ['Catalog validation failed.'];
    return { valid: false, errors: issues };
  }
  return { valid: true, errors: [], spec: catalogRes.data };
}

/** Walks visible elements in tree order starting from spec.root, resolving props against state. */
export function walkUiSpec(spec, visit) {
  if (!spec || typeof spec !== 'object' || !spec.root || !spec.elements) return;
  const stateModel = spec.state && typeof spec.state === 'object' ? spec.state : {};
  const ctx = { stateModel };
  const seen = new Set();
  const walk = (key, depth) => {
    if (!key || seen.has(key) || depth > 24) return;
    const el = spec.elements[key];
    if (!el || typeof el !== 'object') return;
    if (!evaluateVisibility(el.visible, ctx)) return;
    seen.add(key);
    const props = resolveElementProps(el.props || {}, ctx);
    visit({ key, type: el.type, props, element: el, depth });
    if (Array.isArray(el.children)) {
      for (const childKey of el.children) walk(childKey, depth + 1);
    }
  };
  walk(spec.root, 0);
}

/** Extracts all decision Button specs and interactive field specs from a validated json-render Spec. */
export function inspectUiSpecControls(spec) {
  const buttons = [];
  const fields = [];
  const stateModel = spec?.state && typeof spec.state === 'object' ? spec.state : {};
  walkUiSpec(spec, ({ key, type, props }) => {
    if (type === 'Button') {
      const optionId = String(props.optionId || props.decision || key).trim();
      buttons.push({
        key,
        optionId,
        label: String(props.label || optionId),
        tone: props.tone || 'secondary',
        action: props.action || (props.decision ? 'decide' : 'submit'),
        decision: props.decision || null,
        alwaysAllow: props.alwaysAllow || null,
      });
    } else if (type === 'Select' || type === 'ChoiceGroup' || type === 'Toggle' || type === 'TextInput') {
      const stateVal = getByPath(stateModel, `/values/${props.name}`);
      fields.push({
        key,
        type,
        name: String(props.name),
        label: String(props.label),
        hint: props.hint ? String(props.hint) : '',
        options: Array.isArray(props.options) ? props.options : null,
        multiple: Boolean(props.multiple),
        kind: props.kind || 'text',
        optional: Boolean(props.optional),
        secret: Boolean(props.secret),
        defaultValue: stateVal !== undefined ? stateVal : props.defaultValue,
      });
    }
  });
  return { buttons, fields };
}

/** Validates and normalizes submitted field values against the spec's declared interactive inputs. */
export function sanitizeSpecValues(spec, rawValues) {
  const out = {};
  if (!rawValues || typeof rawValues !== 'object' || Array.isArray(rawValues)) return out;
  const { fields } = inspectUiSpecControls(spec);
  for (const f of fields) {
    if (!Object.hasOwn(rawValues, f.name)) continue;
    const raw = rawValues[f.name];
    if (f.type === 'Toggle') {
      if (typeof raw === 'boolean') out[f.name] = raw;
      else if (raw === 'true' || raw === 'on' || raw === '1') out[f.name] = true;
      else if (raw === 'false' || raw === 'off' || raw === '0' || raw === '') out[f.name] = false;
    } else if (f.type === 'Select' || (f.type === 'ChoiceGroup' && !f.multiple)) {
      const val = String(raw ?? '').trim();
      if (f.options?.some((o) => o.value === val)) out[f.name] = val;
    } else if (f.type === 'ChoiceGroup' && f.multiple) {
      const arr = Array.isArray(raw) ? raw : [raw];
      const allowed = new Set((f.options || []).map((o) => o.value));
      out[f.name] = [...new Set(arr.map((v) => String(v ?? '').trim()).filter((v) => allowed.has(v)))];
    } else if (f.type === 'TextInput') {
      if (f.kind === 'number') {
        const num = Number(raw);
        if (Number.isFinite(num)) out[f.name] = num;
      } else {
        out[f.name] = String(raw ?? '').slice(0, 4000);
      }
    }
  }
  return out;
}

/** Looks up an approval decision button by optionId or decision fallback from an approval's uiSpec. */
export function resolveSpecDecisionOption(spec, { optionId = '', decision = '', alwaysAllow = null } = {}) {
  const { buttons } = inspectUiSpecControls(spec);
  const decideButtons = buttons.filter((b) => b.decision === 'approve' || b.decision === 'deny');
  if (optionId) {
    const clean = String(optionId).trim().toLowerCase();
    const hit = decideButtons.find((b) => b.optionId.toLowerCase() === clean);
    if (hit) return hit;
  }
  if (decision === 'approve' && alwaysAllow === 'connection') {
    const hit = decideButtons.find((b) => b.decision === 'approve' && b.alwaysAllow === 'connection');
    if (hit) return hit;
  }
  if (decision === 'approve' && (alwaysAllow === true || alwaysAllow === 'tool')) {
    const hit = decideButtons.find((b) => b.decision === 'approve' && b.alwaysAllow === 'tool');
    if (hit) return hit;
  }
  if (decision === 'approve' || decision === 'deny') {
    const hit = decideButtons.find((b) => b.decision === decision && !b.alwaysAllow)
      || decideButtons.find((b) => b.decision === decision);
    if (hit) return hit;
  }
  return null;
}

function summarizeDetailJson(detail) {
  if (!detail || typeof detail !== 'object') return '';
  const skip = new Set(['connectionId', 'connectionName', 'rule']);
  const cleaned = {};
  for (const [k, v] of Object.entries(detail)) {
    if (skip.has(k) || v === undefined || v === null || v === '') continue;
    cleaned[k] = v;
  }
  if (Object.keys(cleaned).length === 0) return '';
  try {
    const raw = JSON.stringify(cleaned, null, 2);
    return raw.length > 1800 ? `${raw.slice(0, 1797)}...` : raw;
  } catch {
    return '';
  }
}

/**
 * Dynamically builds a validated @json-render/core Spec for ANY Loop approval record.
 * Every field, fact, warning, editable scope control, and decision button is derived from
 * live gateway metadata (never LLM-authored text).
 */
export function buildApprovalUiSpec({
  kind = '',
  target = '',
  title = '',
  reason = '',
  detail = null,
  agentName = 'An agent',
  evalRes = null,
  projects = [],
  canGrantManage = false,
  confirmUrl = '',
} = {}) {
  const safeDetail = detail && typeof detail === 'object' && !Array.isArray(detail) ? detail : {};
  const ruleSource = String(evalRes?.source || safeDetail.rule || '');
  const headline = String(title || target || 'Action requires approval').slice(0, 240);
  const subtitle = String(reason || '').slice(0, 400);
  const elements = {};
  const cardChildren = [];
  const stateValues = {};

  // 1. Dynamic risk callout for destructive, local-command, or agent-access actions.
  const isDelete = safeDetail.action === 'delete' || String(target).includes(':delete:');
  const isLocalAdd = safeDetail.action === 'add_local' || target === 'loop_host__import';
  const isAgentInvite = safeDetail.type === 'agent' && safeDetail.action === 'invite';
  if (isDelete) {
    elements.alert = {
      type: 'Alert',
      props: {
        tone: 'danger',
        text: 'This removes data from Loop and cannot be undone automatically.',
      },
      children: [],
    };
    cardChildren.push('alert');
  } else if (isLocalAdd) {
    elements.alert = {
      type: 'Alert',
      props: {
        tone: 'warn',
        text: 'This runs a local command on your computer. Verify the command before approving.',
      },
      children: [],
    };
    cardChildren.push('alert');
  } else if (isAgentInvite) {
    elements.alert = {
      type: 'Alert',
      props: {
        tone: 'info',
        text: 'Creates a single-use 10-minute connect link for a new agent. You can adjust its scope below.',
      },
      children: [],
    };
    cardChildren.push('alert');
  }

  // 2. Dynamic gateway facts list.
  const facts = [];
  if (target && !headline.includes(String(target))) {
    facts.push({ label: 'Target', value: String(target).slice(0, 200), code: true });
  }
  if (typeof safeDetail.destination === 'string' && safeDetail.destination.trim()) {
    facts.push({ label: 'Destination', value: safeDetail.destination.trim().slice(0, 240), code: true });
  }
  if (isAgentInvite && safeDetail.name) {
    facts.push({ label: 'Agent', value: String(safeDetail.name).slice(0, 120) });
  }
  if (Array.isArray(safeDetail.referencedSecrets) && safeDetail.referencedSecrets.length > 0) {
    facts.push({
      label: 'Vault secrets',
      value: safeDetail.referencedSecrets.map((s) => String(s?.key ?? s)).join(', ').slice(0, 240),
      code: true,
    });
  }
  if (facts.length > 0) {
    elements.facts = {
      type: 'FactList',
      props: { items: facts },
      children: [],
    };
    cardChildren.push('facts');
  }

  // 3. Dynamic owner-editable fields when the action supports live scope customization.
  const fieldKeys = [];
  if (isAgentInvite) {
    const projectOptions = [
      { value: 'all', label: 'All (entire workspace)' },
      ...(Array.isArray(projects)
        ? projects
            .filter((p) => p && typeof p.id === 'string' && p.id && p.id !== 'all')
            .slice(0, 24)
            .map((p) => ({ value: p.id, label: String(p.name || p.id).slice(0, 80) }))
        : []),
    ];
    const requestedProfile = String(safeDetail.profile || 'all');
    const validProfile = projectOptions.some((o) => o.value === requestedProfile) ? requestedProfile : 'all';
    stateValues.profile = validProfile;
    elements.field_profile = {
      type: 'Select',
      props: {
        name: 'profile',
        label: 'Workspace scope',
        hint: 'Limit this agent to one project or allow your whole workspace.',
        options: projectOptions,
        defaultValue: validProfile,
      },
      children: [],
    };
    fieldKeys.push('field_profile');

    const requestedMemory = ['read_write', 'read', 'none'].includes(safeDetail.memoryAccess)
      ? safeDetail.memoryAccess
      : 'read_write';
    stateValues.memoryAccess = requestedMemory;
    elements.field_memory = {
      type: 'Select',
      props: {
        name: 'memoryAccess',
        label: 'Memory access',
        options: [
          { value: 'read_write', label: 'Read & save' },
          { value: 'read', label: 'Read only' },
          { value: 'none', label: 'No memory access' },
        ],
        defaultValue: requestedMemory,
      },
      children: [],
    };
    fieldKeys.push('field_memory');

    if (canGrantManage) {
      const requestedManage = safeDetail.canManage === true;
      stateValues.canManage = requestedManage;
      elements.field_manage = {
        type: 'Toggle',
        props: {
          name: 'canManage',
          label: 'Allow managing connections & settings',
          defaultValue: requestedManage,
        },
        children: [],
      };
      fieldKeys.push('field_manage');
    }
  }

  if (fieldKeys.length > 0) {
    elements.fields = {
      type: 'Stack',
      props: { direction: 'column', gap: 'md' },
      children: fieldKeys,
    };
    cardChildren.push('fields');
  }

  // 4. Collapsible raw details (gateway-verified JSON).
  const rawDetails = summarizeDetailJson(safeDetail);
  if (rawDetails) {
    elements.details = {
      type: 'CodeBlock',
      props: {
        label: 'Details',
        code: rawDetails,
        collapsible: true,
      },
      children: [],
    };
    cardChildren.push('details');
  }

  // 5. Dynamic decision buttons tailored to this approval's policy eligibility.
  // A card can be answered from an agent's app or a text. On Guard it only says no: the yes is on
  // the Loop page, with the Loop password.
  const guard = evalRes?.guard === true;
  const actionChildren = [];
  if (guard) {
    elements.guard = {
      type: 'Alert',
      props: {
        tone: 'warn',
        text: `This is on Guard. To approve it, open Loop and enter your Loop password.${confirmUrl ? ` ${confirmUrl}` : ''}`.slice(0, 400),
      },
      children: [],
    };
    cardChildren.unshift('guard');
  } else {
    elements.btn_approve = {
      type: 'Button',
      props: {
        label: 'Yes — Approve',
        tone: 'primary',
        action: 'decide',
        optionId: 'approve',
        decision: 'approve',
      },
      children: [],
    };
    actionChildren.push('btn_approve');
  }

  const alwaysAllowable = canAlwaysAllow({ kind, guard, detail: { rule: ruleSource } });
  const canAlwaysAllowTool = alwaysAllowable && typeof target === 'string' && target.includes('__');
  if (canAlwaysAllowTool) {
    elements.btn_always_tool = {
      type: 'Button',
      props: {
        label: 'Yes — Approve & always allow this tool',
        tone: 'secondary',
        action: 'decide',
        optionId: 'approve_always_tool',
        decision: 'approve',
        alwaysAllow: 'tool',
      },
      children: [],
    };
    actionChildren.push('btn_always_tool');
  }

  const connId = typeof safeDetail.connectionId === 'string' ? safeDetail.connectionId.trim() : '';
  const connName = String(safeDetail.connectionName || connId || 'this connection').trim().slice(0, 60);
  const canAlwaysAllowConn =
    alwaysAllowable &&
    Boolean(connId) &&
    ruleSource.startsWith('toolKind:');
  if (canAlwaysAllowConn) {
    elements.btn_always_conn = {
      type: 'Button',
      props: {
        label: `Yes — Always allow all of ${connName}`,
        tone: 'secondary',
        action: 'decide',
        optionId: 'approve_always_connection',
        decision: 'approve',
        alwaysAllow: 'connection',
      },
      children: [],
    };
    actionChildren.push('btn_always_conn');
  }

  elements.btn_deny = {
    type: 'Button',
    props: {
      label: 'No — Deny',
      tone: 'danger',
      action: 'decide',
      optionId: 'deny',
      decision: 'deny',
    },
    children: [],
  };
  actionChildren.push('btn_deny');

  elements.actions = {
    type: 'ActionGroup',
    props: { layout: actionChildren.length <= 2 ? 'grid' : 'stack' },
    children: actionChildren,
  };
  cardChildren.push('actions');

  elements.root = {
    type: 'Card',
    props: {
      kicker: `${String(agentName || 'An agent').slice(0, 80)} asked for your OK`,
      title: headline,
      ...(subtitle ? { subtitle } : {}),
      tone: isDelete ? 'danger' : isLocalAdd ? 'warn' : 'default',
    },
    children: cardChildren,
  };

  const spec = {
    root: 'root',
    elements,
    state: { values: stateValues },
  };
  const checked = validateUiSpec(spec);
  return checked.valid ? checked.spec : spec;
}

/**
 * Compiles any validated @json-render/core Spec into an MCP `elicitation/create` params payload
 * (supporting both 2025-11-25 `oneOf` + `mode` and 2025-06-18 `enum` + `enumNames`).
 */
export function specToMcpElicitation(spec, { approveUrl = null, protocolVersion = '2025-11-25', useForm = true, elicitationId = '' } = {}) {
  const lines = [];
  walkUiSpec(spec, ({ type, props }) => {
    if (type === 'Card') {
      if (props.title) lines.push(`Loop approval required: ${props.title}`);
      if (props.subtitle) lines.push(`Reason: ${props.subtitle}`);
    } else if (type === 'Alert') {
      if (props.text) lines.push(`Note: ${props.text}`);
    } else if (type === 'Heading') {
      if (props.text) lines.push(props.text);
    } else if (type === 'Text') {
      if (props.text) lines.push(props.text);
    } else if (type === 'FactList' && Array.isArray(props.items)) {
      for (const item of props.items) {
        lines.push(`${item.label}: ${item.value}`);
      }
    } else if (type === 'CodeBlock' && props.code) {
      const compact = String(props.code).replace(/\s+/g, ' ').trim();
      if (compact && compact !== '{}') {
        lines.push(`${props.label || 'Details'}: ${compact.length > 260 ? `${compact.slice(0, 257)}...` : compact}`);
      }
    }
  });
  if (!useForm && approveUrl) {
    lines.push(`Web link: ${approveUrl}`);
  }
  const message = lines.join('\n') || 'Loop approval required';

  if (!useForm) {
    return {
      mode: 'url',
      elicitationId: String(elicitationId || ''),
      url: String(approveUrl || ''),
      message,
    };
  }

  const is202511 = String(protocolVersion || '') >= '2025-11-25';
  const { buttons, fields } = inspectUiSpecControls(spec);
  const properties = {};
  const required = [];

  const decideButtons = buttons.filter((b) => b.decision === 'approve' || b.decision === 'deny');
  if (decideButtons.length > 0) {
    properties.decision = is202511
      ? {
          type: 'string',
          title: 'Decision',
          description: 'Choose whether to allow this action in Loop',
          oneOf: decideButtons.map((b) => ({ const: b.optionId, title: b.label })),
        }
      : {
          type: 'string',
          title: 'Decision',
          description: 'Choose whether to allow this action in Loop',
          enum: decideButtons.map((b) => b.optionId),
          enumNames: decideButtons.map((b) => b.label),
        };
    required.push('decision');
  }

  for (const f of fields) {
    if (f.secret) continue; // Never pass secrets through MCP form elicitation.
    if (f.type === 'Select' || (f.type === 'ChoiceGroup' && !f.multiple)) {
      const opts = f.options || [];
      if (!opts.length) continue;
      properties[f.name] = is202511
        ? {
            type: 'string',
            title: f.label,
            ...(f.hint ? { description: f.hint } : {}),
            oneOf: opts.map((o) => ({ const: o.value, title: o.label })),
            ...(typeof f.defaultValue === 'string' ? { default: f.defaultValue } : {}),
          }
        : {
            type: 'string',
            title: f.label,
            ...(f.hint ? { description: f.hint } : {}),
            enum: opts.map((o) => o.value),
            enumNames: opts.map((o) => o.label),
            ...(typeof f.defaultValue === 'string' ? { default: f.defaultValue } : {}),
          };
    } else if (f.type === 'Toggle') {
      properties[f.name] = {
        type: 'boolean',
        title: f.label,
        ...(f.hint ? { description: f.hint } : {}),
        ...(typeof f.defaultValue === 'boolean' ? { default: f.defaultValue } : {}),
      };
    } else if (f.type === 'TextInput') {
      properties[f.name] = {
        type: f.kind === 'number' ? 'number' : 'string',
        title: f.label,
        ...(f.hint ? { description: f.hint } : {}),
        ...(f.defaultValue !== undefined && f.defaultValue !== '' ? { default: f.defaultValue } : {}),
      };
    }
  }

  return {
    ...(is202511 ? { mode: 'form' } : {}),
    message,
    requestedSchema: {
      type: 'object',
      properties,
      required,
    },
  };
}

/** Parses an MCP `elicitation/create` client response against the originating json-render Spec. */
export function parseMcpElicitationAnswer(spec, clientReply, { useForm = true } = {}) {
  if (!clientReply || clientReply.error) return { outcome: 'fallback' };
  const result = clientReply.result;
  if (!result || typeof result !== 'object') return { outcome: 'fallback' };
  const action = String(result.action || '').trim().toLowerCase();
  if (action === 'decline' || action === 'cancel') return { outcome: 'deny', optionId: 'deny', values: {} };
  if (action !== 'accept') return { outcome: 'fallback' };
  if (!useForm) return { outcome: 'url_opened', values: {} };

  const content = result.content && typeof result.content === 'object' ? result.content : {};
  const rawChoice = String(content.decision || '').trim().toLowerCase();
  const values = sanitizeSpecValues(spec, content);
  const opt = resolveSpecDecisionOption(spec, {
    optionId: rawChoice,
    decision: rawChoice === 'yes' ? 'approve' : rawChoice === 'no' ? 'deny' : rawChoice,
  });
  if (!opt || opt.decision === 'deny') {
    return { outcome: 'deny', optionId: opt?.optionId || 'deny', values };
  }
  return {
    outcome: opt.alwaysAllow === 'connection'
      ? 'approve_always_connection'
      : opt.alwaysAllow === 'tool'
        ? 'approve_always_tool'
        : 'approve',
    optionId: opt.optionId,
    alwaysAllow: opt.alwaysAllow || null,
    values,
  };
}

