const SAFE_HTTP_URL_SCHEMA = z.string().min(1).max(2048).refine((raw) => {
  try {
    const u = new URL(raw);
    return (u.protocol === 'http:' || u.protocol === 'https:') && !u.username && !u.password;
  } catch {
    return false;
  }
}, 'URL must use http or https without embedded credentials.');

const DATA_IMAGE_RE = /^data:image\/(png|jpeg|jpg|webp|gif);base64,[A-Za-z0-9+/=]+$/i;

export function isSafeCardImageUrl(raw) {
  if (typeof raw !== 'string') return false;
  const trimmed = raw.trim();
  if (!trimmed) return false;
  if (trimmed.length <= 512_000 && DATA_IMAGE_RE.test(trimmed)) return true;
  if (trimmed.length > 2048) return false;
  try {
    const u = new URL(trimmed);
    if (u.username || u.password) return false;
    if (u.protocol === 'https:') return true;
    if (u.protocol === 'http:' && (u.hostname === '127.0.0.1' || u.hostname === 'localhost')) return true;
  } catch {
    return false;
  }
  return false;
}

const SAFE_IMAGE_URL_SCHEMA = z
  .string()
  .min(1)
  .max(512_000)
  .refine(isSafeCardImageUrl, 'Image URL must use https, localhost http, or a base64 PNG/JPEG/WebP/GIF data URI.');

