export const savedCardCatalog = defineCatalog(loopUiSchema, {
  components: SAVED_CARD_COMPONENTS,
  actions: {},
});

const MAX_SAVED_CARD_ELEMENTS = 64;
const ALLOWED_SAVED_CARD_TYPES = new Set(Object.keys(SAVED_CARD_COMPONENTS));

// What a saved card looks like, for an agent that sent another shape (most often a nested tree).
const SAVED_CARD_SHAPE = 'ui is a flat json-render card: { root: "<element id>", elements: { "<id>": { type, props, children?: ["<id>"] } } }. For example { "root": "card", "elements": { "card": { "type": "Card", "props": { "title": "Report" }, "children": ["text"] }, "text": { "type": "Text", "props": { "text": "Done." } } } }.';

/** Strictly validates a read-only json-render Spec for Saved items and Agent Artifacts. */
export function validateSavedCardSpec(spec) {
  if (!spec || typeof spec !== 'object' || Array.isArray(spec)) {
    return { valid: false, errors: [`ui must be a JSON object. ${SAVED_CARD_SHAPE}`] };
  }
  const elements = spec.elements && typeof spec.elements === 'object' && !Array.isArray(spec.elements)
    ? spec.elements
    : null;
  const keys = elements ? Object.keys(elements) : [];
  if (!elements || keys.length === 0 || keys.length > MAX_SAVED_CARD_ELEMENTS) {
    return { valid: false, errors: [`ui.elements must contain between 1 and ${MAX_SAVED_CARD_ELEMENTS} elements. ${SAVED_CARD_SHAPE}`] };
  }
  const propErrors = [];
  const specState = spec.state && typeof spec.state === 'object' ? spec.state : {};
  for (const [k, def] of Object.entries(elements)) {
    if (!def || typeof def !== 'object') {
      return { valid: false, errors: [`Element "${k}" must be an object.`] };
    }
    if (!ALLOWED_SAVED_CARD_TYPES.has(def.type)) {
      return {
        valid: false,
        errors: [
          `Element "${k}" uses unsupported or interactive component "${def.type}". Permitted components: ${[...ALLOWED_SAVED_CARD_TYPES].join(', ')}.`,
        ],
      };
    }
    if (def.on !== undefined) {
      return { valid: false, errors: [`Element "${k}" cannot define interactive actions in a read-only saved card.`] };
    }
    const rawProps = def.props ?? {};
    if (typeof rawProps !== 'object' || rawProps === null || Array.isArray(rawProps)) {
      propErrors.push(`Element "${k}" (${def.type}): props must be an object.`);
      continue;
    }
    const resolvedProps = resolveCardProps(rawProps, specState);
    if (def.type === 'Link') {
      const rawUrl = String(resolvedProps.url || '').trim();
      let parsed = null;
      try { parsed = new URL(rawUrl); } catch { parsed = null; }
      if (!parsed || (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') || parsed.username || parsed.password) {
        return { valid: false, errors: [`Link "${k}" must use a safe http or https URL without credentials.`] };
      }
    }
    if (def.type === 'Image') {
      if (!isSafeCardImageUrl(resolvedProps.url)) {
        return { valid: false, errors: [`Image "${k}" must use https, localhost http, or a base64 PNG/JPEG/WebP/GIF data URI.`] };
      }
    }
    if (def.type === 'ItemList' && Array.isArray(resolvedProps.items)) {
      for (const item of resolvedProps.items) {
        if (item?.url !== undefined) {
          let parsed = null;
          try { parsed = new URL(String(item.url).trim()); } catch { parsed = null; }
          if (!parsed || (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') || parsed.username || parsed.password) {
            return { valid: false, errors: [`ItemList "${k}" item url must use a safe http or https URL without credentials.`] };
          }
        }
      }
    }
    const compDef = SAVED_CARD_COMPONENTS[def.type];
    const propsSchema = typeof compDef?.props?.strict === 'function' ? compDef.props.strict() : compDef?.props;
    if (propsSchema) {
      const checked = propsSchema.safeParse(resolvedProps);
      if (!checked.success) {
        for (const issue of checked.error.issues) {
          const p = issue.path.length ? `.${issue.path.join('.')}` : '';
          propErrors.push(`Element "${k}" (${def.type}) props${p}: ${issue.message}`);
        }
      }
    }
  }
  if (propErrors.length > 0) {
    return { valid: false, errors: propErrors };
  }
  const structural = validateSpec(spec);
  if (!structural.valid) {
    return {
      valid: false,
      errors: structural.issues.filter((i) => i.severity === 'error').map((i) => i.message),
    };
  }
  const catalogRes = savedCardCatalog.validate(spec);
  if (!catalogRes.success) {
    const issues = catalogRes.error?.issues?.map((i) => `${i.path.join('.') || 'ui'}: ${i.message}`)
      || ['Saved card catalog validation failed.'];
    return { valid: false, errors: issues };
  }
  return { valid: true, errors: [], spec: catalogRes.data };
}

function escapeMdCell(raw) {
  return String(raw ?? '').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ').trim();
}

function evalCardVisible(cond, state) {
  if (cond === undefined || cond === null || cond === true) return true;
  if (cond === false) return false;
  if (Array.isArray(cond)) return cond.every((c) => evalCardVisible(c, state));
  if (typeof cond !== 'object') return Boolean(cond);
  if (Array.isArray(cond.$and)) return cond.$and.every((c) => evalCardVisible(c, state));
  if (Array.isArray(cond.$or)) return cond.$or.some((c) => evalCardVisible(c, state));
  if (typeof cond.$state === 'string') {
    const val = getByPath(state, cond.$state);
    if (Object.hasOwn(cond, 'eq')) return val === cond.eq;
    if (Object.hasOwn(cond, 'neq')) return val !== cond.neq;
    if (cond.not) return !val;
    return Boolean(val);
  }
  try {
    return evaluateVisibility(cond, { stateModel: state });
  } catch {
    return true;
  }
}

function resolveCardProps(raw, state) {
  const out = {};
  for (const [k, v] of Object.entries(raw || {})) {
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      if (typeof v.$state === 'string') out[k] = getByPath(state, v.$state);
      else if (typeof v.$bindState === 'string') out[k] = getByPath(state, v.$bindState);
      else out[k] = v;
    } else {
      out[k] = v;
    }
  }
  return out;
}

/**
 * Compiles any validated read-only @json-render/core card Spec into clean GitHub-Flavored Markdown
 * for CLI/IDE hosts (Codex, Claude Code, Cursor, Gemini CLI) that do not render MCP App iframes.
 */
export function renderCardSpecToMarkdown(spec) {
  if (!spec || typeof spec !== 'object' || typeof spec.root !== 'string' || !spec.elements) {
    return '';
  }
  const state = spec.state && typeof spec.state === 'object' ? spec.state : {};
  const seen = new Set();

  const renderNode = (key, depth = 0) => {
    if (!key || seen.has(key) || depth > 20) return '';
    const def = spec.elements[key];
    if (!def || typeof def !== 'object') return '';
    if (!evalCardVisible(def.visible, state)) return '';
    seen.add(key);

    const p = resolveCardProps(def.props, state);
    const childBlocks = (Array.isArray(def.children) ? def.children : [])
      .map((ck) => renderNode(ck, depth + 1))
      .filter(Boolean);

    if (def.type === 'Card') {
      const parts = [];
      if (p.kicker) parts.push(`*${String(p.kicker).trim()}*`);
      if (p.title) parts.push(`### ${String(p.title).trim()}`);
      if (p.subtitle) parts.push(String(p.subtitle).trim());
      if (childBlocks.length) parts.push(...childBlocks);
      return parts.join('\n\n');
    }
    if (def.type === 'Stack') {
      if (p.direction === 'row') {
        const inline = childBlocks.every((b) => !b.includes('\n'));
        return inline ? childBlocks.join(' · ') : childBlocks.join('\n\n');
      }
      return childBlocks.join('\n\n');
    }
    if (def.type === 'Heading') {
      const hashes = p.level === 1 ? '##' : p.level === 3 ? '####' : '###';
      return `${hashes} ${String(p.text || '').trim()}`;
    }
    if (def.type === 'Text') {
      const t = String(p.text || '').trim();
      if (!t) return '';
      return p.bold ? `**${t}**` : t;
    }
    if (def.type === 'Badge') {
      const lbl = String(p.label || '').trim();
      return lbl ? `\`${lbl}\`` : '';
    }
    if (def.type === 'Alert' || def.type === 'Callout') {
      const head = p.title ? `**${String(p.title).trim()}:** ` : '';
      return `> ${head}${String(p.text || '').trim()}`;
    }
    if (def.type === 'Link') {
      const label = String(p.label || p.url || '').trim();
      const url = String(p.url || '').trim();
      const desc = p.description ? ` — ${String(p.description).trim()}` : '';
      if (!url) return label;
      return p.variant === 'primary' ? `**[${label}](${url})**${desc}` : `[${label}](${url})${desc}`;
    }
    if (def.type === 'Progress') {
      const maxVal = Number(p.max) > 0 ? Number(p.max) : 100;
      const pct = Math.max(0, Math.min(100, Math.round((Number(p.value || 0) / maxVal) * 100)));
      const filled = Math.round(pct / 10);
      const bar = `${'█'.repeat(filled)}${'░'.repeat(10 - filled)}`;
      const cap = p.caption ? ` — ${String(p.caption).trim()}` : '';
      return `**${String(p.label || 'Progress').trim()}:** \`${bar}\` **${pct}%**${cap}`;
    }
    if (def.type === 'BarChart') {
      const items = Array.isArray(p.items) ? p.items : [];
      if (!items.length) return '';
      const maxVal = Math.max(1, ...items.map((it) => Number(it.value) || 0));
      const lines = [];
      if (p.title) lines.push(`**${String(p.title).trim()}**`, '');
      lines.push('| Item | Level | Value |', '| --- | --- | --- |');
      for (const it of items) {
        const ratio = Math.max(0, Math.min(1, (Number(it.value) || 0) / maxVal));
        const filled = Math.max(ratio > 0 ? 1 : 0, Math.round(ratio * 10));
        const bar = `\`${'█'.repeat(filled)}${'░'.repeat(10 - filled)}\``;
        const valText = it.displayValue ? String(it.displayValue) : String(it.value ?? 0);
        lines.push(`| ${escapeMdCell(it.label || '')} | ${bar} | **${escapeMdCell(valText)}** |`);
      }
      return lines.join('\n');
    }
    if (def.type === 'Steps') {
      const items = Array.isArray(p.items) ? p.items : [];
      const marks = { done: '✓', active: '▸', pending: '○', error: '✗' };
      return items
        .map((it) => {
          const mark = marks[it.status] || '○';
          const det = it.detail ? ` — ${String(it.detail).trim()}` : '';
          return `- ${mark} **${String(it.label || '').trim()}**${det}`;
        })
        .join('\n');
    }
    if (def.type === 'ItemList') {
      const items = Array.isArray(p.items) ? p.items : [];
      return items
        .map((it) => {
          const badge = it.badge ? ` \`${String(it.badge).trim()}\`` : '';
          const sub = it.subtitle ? ` — ${String(it.subtitle).trim()}` : '';
          const act = it.url ? ` · [${String(it.actionLabel || 'Open').trim()}](${String(it.url).trim()})` : '';
          return `- **${String(it.title || '').trim()}**${badge}${sub}${act}`;
        })
        .join('\n');
    }
    if (def.type === 'Tabs') {
      const tabs = Array.isArray(p.items) ? p.items : [];
      return tabs
        .map((t) => {
          const body = t?.elementId ? renderNode(t.elementId, depth + 1) : '';
          if (!body) return '';
          return `#### ${String(t.label || '').trim()}\n\n${body}`;
        })
        .filter(Boolean)
        .join('\n\n');
    }
    if (def.type === 'Image') {
      const url = String(p.url || '').trim();
      const alt = String(p.alt || p.caption || 'Visual').trim();
      const cap = p.caption ? `\n*${String(p.caption).trim()}*` : '';
      if (/^https?:\/\//i.test(url)) return `![${alt}](${url})${cap}`;
      return `*[Image: ${alt}]*${cap}`;
    }
    if (def.type === 'Metric') {
      const chg = p.change ? ` (${String(p.change).trim()})` : '';
      return `**${String(p.label || '').trim()}:** ${String(p.value || '').trim()}${chg}`;
    }
    if (def.type === 'MetricGrid') {
      const items = Array.isArray(p.items) ? p.items : [];
      if (!items.length) return '';
      const cols = items.map((it) => escapeMdCell(it.label || ''));
      const vals = items.map((it) => {
        const chg = it.change ? ` (${escapeMdCell(it.change)})` : '';
        return `**${escapeMdCell(it.value || '')}**${chg}`;
      });
      return [
        `| ${cols.join(' | ')} |`,
        `| ${cols.map(() => '---').join(' | ')} |`,
        `| ${vals.join(' | ')} |`,
      ].join('\n');
    }
    if (def.type === 'FactList') {
      const items = Array.isArray(p.items) ? p.items : [];
      return items
        .map((it) => {
          const val = it.code ? `\`${String(it.value || '')}\`` : String(it.value || '');
          return `- **${String(it.label || '').trim()}:** ${val}`;
        })
        .join('\n');
    }
    if (def.type === 'List') {
      const items = Array.isArray(p.items) ? p.items : [];
      return items.map((it, i) => (p.ordered ? `${i + 1}. ${it}` : `- ${it}`)).join('\n');
    }
    if (def.type === 'Checklist') {
      const items = Array.isArray(p.items) ? p.items : [];
      return items.map((it) => `- [${it.checked ? 'x' : ' '}] ${String(it.label || '').trim()}`).join('\n');
    }
    if (def.type === 'Table') {
      const cols = Array.isArray(p.columns) ? p.columns : [];
      const rows = Array.isArray(p.rows) ? p.rows : [];
      if (!cols.length) return '';
      const lines = [
        `| ${cols.map(escapeMdCell).join(' | ')} |`,
        `| ${cols.map(() => '---').join(' | ')} |`,
      ];
      for (const row of rows) {
        const cells = cols.map((_, idx) => escapeMdCell(Array.isArray(row) ? row[idx] : ''));
        lines.push(`| ${cells.join(' | ')} |`);
      }
      return lines.join('\n');
    }
    if (def.type === 'CodeBlock') {
      const lbl = p.label ? `**${String(p.label).trim()}**\n` : '';
      return `${lbl}\`\`\`\n${String(p.code || '')}\n\`\`\``;
    }
    if (def.type === 'Divider') {
      return '---';
    }
    return '';
  };

  return renderNode(spec.root, 0).trim();
}
